import{_ as e,o,c as i,ag as a}from"./chunks/plugin-vue_export-helper.BT7B-090.js";const u=JSON.parse('{"title":"Токсики это правила-соблюдатели","description":"","frontmatter":{"site":"pro","title":"Токсики это правила-соблюдатели","date":"2026-11-03T00:00:00.000Z","source":"https://t.me/jfyi_ps/124","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-11-03-toksiki-eto-pravila-soblyudateli"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Токсики это правила-соблюдатели"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-11-03-toksiki-eto-pravila-soblyudateli"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Токсики это правила-соблюдатели"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Токсики это правила-соблюдатели\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-11-03-toksiki-eto-pravila-soblyudateli\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-11-03\\"}"]]},"headers":[],"relativePath":"posts/2026-11-03-toksiki-eto-pravila-soblyudateli.md","filePath":"posts/2026-11-03-toksiki-eto-pravila-soblyudateli.md"}'),p={name:"posts/2026-11-03-toksiki-eto-pravila-soblyudateli.md"};function r(n,t,s,l,c,d){return o(),i("div",null,[...t[0]||(t[0]=[a("<p>Больше всего в жизни меня бесит когда что-то называют не тем, чем оно является.</p><p>Гарвард, 2015 год, Housman &amp; Minor, Toxic Workers (HBS Working Paper 16-057). Избежать найма одного токсичного работника стоит 12 489 долларов, а нанять звезду из верхнего 1% - 5 303. Токсик дороже звезды вдвое. И вторая деталь, от которой должно щёлкнуть: токсичные сотрудники систематически описывают себя как уверенных в себе людей, которые “всегда соблюдают правила”. Не бунтари. Правила-соблюдатели.</p><p>Бабяк, Ньюман и Хэйр, 2010 год, Corporate Psychopathy: Talking the Walk. 203 корпоративных руководителя. Психопатия выше порога - примерно у 4% против 1% в популяции. И самое вкусное: этих людей начальство высоко оценивало по шкалам “коммуникативные навыки”, “креативность”, “стратегическое мышление” - и низко по шкалам “работа в команде”, “стиль управления” и общая результативность.</p><p>То есть гений общения с провалом по результату - это измеренный профиль.</p><p>Шарлан Неметт, Беркли, тридцать лет опытов. Подлинное несогласие меньшинства запускает дивергентное мышление и улучшает решения группы. Назначенный “адвокат дьявола” - нет, он даже укрепляет позицию большинства. Разница между человеком, который реально не согласен, и человеком, который играет роль, видна в результате.</p><p>Эми Эдмондсон, 1999 год, исследование больничных бригад. Команда, где “всё хорошо”, - это не здоровая команда. Это команда с выключенной сигнализацией.</p><p>Милликен, Моррисон и Хьюлин, 2003 год: 85% сотрудников хотя бы раз промолчали о проблеме, которую считали важной.</p><p>Хиршман, 1970 год, Exit, Voice, and Loyalty. Голос - это функция лояльности. Тому, кто уже мысленно уволился, незачем орать, он молча обновляет резюме. Орёт тот, кто ещё собирается здесь работать. Молчание - не признак здоровья, это просто отложенный разговор.</p><p>Поэтому ярлык “токсик” - самый дешёвый ремонт процесса из существующих. Чинить процесс дорого. Объявить дефектным человека, который на него показывает, - бесплатно.</p><p>И да, “улыбнись и не выноси”. Батлер и коллеги, 2003 год, The Social Consequences of Expressive Suppression. Подавление эмоций поднимает давление не только у того, кто терпит, но и у собеседника. Ты не сохраняешь атмосферу. Ты просто делишься гипертонией на двоих.</p><p>Теперь блейминг.</p><p>“Негатив о прошлом работодателе - всегда красный флаг”. Это не наука, это фольклор собеседований. Сакетт и коллеги, 2022 год, пересчёт метаанализов валидности методов отбора. Неструктурированное интервью - 0,19, структурированное - 0,42. Твоё нутряное “что-то он мутный” предсказывает будущую работу примерно вдвое хуже, чем одни и те же вопросы всем кандидатам. Красный флаг у тебя в голове, а не у меня в трудовой.</p><p>При этом Gallup стабильно показывает: руководитель объясняет около 70% дисперсии вовлечённости команды. Люди уходят от начальника - это не жалоба, это статистика. Требовать от человека нейтрального отзыва о системе, которая его перемолола, - требовать врать в первом же вопросе.</p>",13)])])}const g=e(p,[["render",r]]);export{u as __pageData,g as default};
